  [24318] = { "$D1の間、術者の攻撃速度を$N1%、術者が与えるPhysicalダメージを$N2増加させます。", "与える物理ダメージが$N1増加しています。\n攻撃速度が$N2%上昇しています。", 0x1d3f8a49, 0xbc6c8e1d, "uu" },
  [24321] = { nil, "$D1ごとに$N1のダメージを与えます。", nil, 0x2af65718, "mu" },
  [24322] = { nil, "毎秒$N1のダメージを与えます。\n毎秒体力を$N2、Hakkarに与えています。", nil, 0x1bda21b6, "mu" },
  [24323] = { nil, "あなたの血には毒があります！\n毎秒Hakkarに$N1のダメージを与えています。", nil, 0x181901e2, "mu" },
  [24325] = { "Zulian Mudskunkを$N1匹セットし、Zul'GurubのPagle's Pointから投げ込みます。", nil, 0x3b67bb75, nil, "um" },
  [24326] = { "近くの敵に通常のダメージに加えて$N1のダメージを与え、吹き飛ばします。", nil, 0x82914e2a, nil, "um" },
  [24327] = { "敵の対象を一時的に狂乱させ、$D1の間、攻撃速度を$N1%、移動速度を$N2%上げ、さらに味方を攻撃させます。", "魅了されています。\n攻撃速度が$N1%上昇しています。\n移動速度が$N2%上昇しています。", 0x5f517374, 0x5efc4777, "uu" },
  [24328] = { nil, "$D1ごとに$N1のダメージを与えます。", nil, 0x17e4d127, "mu" },
  [24331] = { "対象を引き裂いて$N1のダメージを与え、さらに$D1かけて$N2のダメージを与えます。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0xd23334a8, 0x59c933ab, "uu" },
  [24332] = { "対象を引き裂いて$N1のダメージを与え、さらに$D1かけて$N2のダメージを与えます。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0xd23334a8, 0x59c933ab, "uu" },
  [24333] = { "敵に通常ダメージに加えて$N1を与え、$D1の間スタンさせます。", "スタンしています。", 0x16b62254, 0x27f95286, "uu" },
  [24334] = { "敵にNatureダメージを与えます。", nil, 0x6878f321, nil, "um" },
  [24335] = { "対象を$D1の間眠らせる毒針の射撃です。ダメージを受けると効果は解けます。対象が目覚めると、Stingが$D2かけて$N2のNatureダメージを与えます。", "眠っています。", 0xcd595839, 0x5339954e, "uu" },
  [24336] = { nil, "$N2秒ごとに$N1のNatureダメージを受けます。", nil, 0xda01d472, "mu" },
  [24337] = { "対象を待ち伏せし、$N1のダメージを与えます。", nil, 0x4cf51d17, nil, "um" },
  [24339] = { "$D2の間、$D1ごとに敵にNatureダメージを与え、その敵が受けるPhysicalダメージを増加させます。", "$D1ごとに$N1の自然ダメージを受けています。\n受けるPhysicalダメージが$N3増加しています。", 0x492d5d05, 0xfd5c46ab, "uu" },
  [24340] = { "効果を受けるすべての対象に均等に分けたダメージを与えます", nil, 0x4e959530, nil, "um" },
  [24346] = { "あなたを魚に変え、移動速度を上げますが、呪文の詠唱や攻撃はできなくなります。", nil, 0x8aa8f0b7, nil, "um" },
  [24347] = { "frenzy fishに変身し、水中呼吸が可能になり、水泳速度が$N1%上昇します。\n\n泳いでいる間のみ使用できます。一部の戦闘行動でこの効果は解除されます。", "水中で呼吸でき、泳ぐ速度が$N1%上昇しています。戦闘中の行動によってはこの効果が解けることがあります。", 0x431016e5, 0xd2bc7f95, "uu" },
  [24348] = { nil, "Aspect of the Cheetahによる移動速度ボーナスが$N1上昇します。", nil, 0xf50798e1, "mu" },
  [24350] = { "落下によるダメージを軽減します。", nil, 0x879f36dd, nil, "um" },
  [24351] = { "自分に対するFear効果の命中率を$N1%低下させます。", nil, 0xd3bb670e, nil, "um" },
  [24352] = { "$D1以内に行う次の近接攻撃または遠隔攻撃で、対象を$D2の間Rootします。対象が移動中だった場合、この効果の持続時間が倍になります。Beastsにのみ有効です。", nil, 0x70208c01, nil, "um" },
  [24353] = { "$D1以内に詠唱する次のRevive Petのマナコストを$N2%軽減します。", "Revive Petのマナコストが$N1%減少しています。", 0x3af67b64, 0xc292e046, "uu" },
  [24354] = { "対象を$N1回復します。Silencedの状態でも使用できます。", "$N1回復します。", 0x350c8950, 0x435edd54, "uu" },
  [24355] = { "$D1の間、毎秒マナの$N1%を回復します。回復中は座っている必要があります。", "毎秒マナの$N1%を回復します。", 0x0f5f34b8, 0x408e795a, "uu" },
  [24357] = { "わずかにステルス検出は増加します。", nil, 0x7533986c, nil, "um" },
  [24360] = { "飲んだ者を$D1の間、夢のない眠りに就かせます。その間、体力を$N2、マナを$N3回復します。", "Dreamless Sleepの状態です。", 0x34e223e7, 0xdc16b705, "uu" },
  [24361] = { "$D2の間、5秒ごとに体力を$N1回復します。", "$N2秒ごとに体力を$N1回復します。", 0xc7f103fb, 0x65af5ffa, "uu" },
  [24362] = { "Fist Weaponsが+$N1上昇します。", nil, 0xcffc0304, nil, "um" },
  [24363] = { "$D2の間、5秒ごとにマナを$N1回復します。", "5秒ごとにマナを$N1回復します。", 0xa58964ae, 0xdc8a840b, "uu" },
  [24364] = { "次の$D1の間、StunとMovement Impairingの効果を無効にします。さらに、現在かかっているStunとMovement Impairingの効果を解除します。", "Free Actionの状態です。", 0x00112373, 0x97eb1d67, "uu" },
  [24365] = { "1時間30であなたの精神を向上させます。バトルエリクサー。", nil, 0x4778d63c, nil, "um" },
  [24366] = { "12秒のために夢を見ない睡眠で大酒飲みを置きます。その時に大酒飲みは、1416年の健康と2100マナを回復する。", nil, 0x306d36ff, nil, "um" },
  [24367] = { "気絶させると次の3秒のための運動性を損なう影響は免疫ができます。また、既存のスタンと動きを損なう効果が削除されます。", nil, 0x7e663362, nil, "um" },
  [24368] = { "1時間ごとに5秒20の健康を再生成します。ガーディアンエリクサー。", nil, 0x70477e6d, nil, "um" },
